function Counter({ end, label }) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    let cur = 0;
    const step = end / 90;
    const t = setInterval(() => {
      cur += step;
      if (cur >= end) { setVal(end); clearInterval(t); }
      else setVal(Math.floor(cur));
    }, 16);
    return () => clearInterval(t);
  }, [end]);
  return (
    <div style={{ textAlign:"center" }}>
      <div style={{ fontSize:32, fontWeight:900, color:"#3a3632" }}>{val.toLocaleString()}+</div>
      <div style={{ fontSize:11, color:"#a8a098", marginTop:4 }}>{label}</div>
    </div>
  );
}

